<script setup>
import {ref,onMounted,watch,onUnmounted} from 'vue'
import {api} from '../lib/api'
const search=ref(''),students=ref([]),studentId=ref(''),amount=ref(100),reason=ref(''),account=ref(null),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),dialog=ref(null);let requestKey=crypto.randomUUID(),lookup=0,alive=true
async function find(){const current=++lookup;try{const result=await api('/admin/message-recipients?'+new URLSearchParams({search:search.value}));if(alive&&lookup===current)students.value=result.items}catch(e){if(alive)error.value=e.message}}
async function load(){const id=studentId.value;account.value=null;if(!id)return;loading.value=true;error.value='';try{const result=await api('/admin/students/'+id+'/points');if(alive&&studentId.value===id)account.value=result}catch(e){if(alive)error.value=e.message}finally{if(alive&&studentId.value===id)loading.value=false}}
watch(studentId,load)
watch([studentId,amount,reason],()=>{if(!busy.value){requestKey=crypto.randomUUID();message.value=''}},{flush:'sync'})
function review(){error.value='';if(!account.value||!Number.isSafeInteger(amount.value)||amount.value<1||amount.value>1000000||!reason.value.trim()){error.value='학생·지급 포인트·사유를 확인하세요.';return}dialog.value.showModal()}
async function grant(){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/admin/students/'+studentId.value+'/points',{method:'POST',body:{amount:amount.value,reason:reason.value,requestKey}});account.value=result;message.value=result.duplicate?'이미 처리된 지급이에요. 추가 지급하지 않았습니다.':account.value.student.name+' 학생에게 '+amount.value.toLocaleString()+' P를 지급했어요.';requestKey=crypto.randomUUID();reason.value='';dialog.value.close()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(find);onUnmounted(()=>{alive=false;lookup++;dialog.value?.close()})
</script>
<template><section class="panel admin-point-grants"><div class="mailbox-heading"><h2>학생 포인트 지급</h2><span>관리자 보너스</span></div><p>학생에게 보너스 포인트를 지급합니다. 퀴즈 최초 정답 보상과 별도로 내역에 기록돼요.</p><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="error&&!dialog?.open" class="notice" role="alert">{{error}}</p><form class="point-grant-form" @submit.prevent="review"><fieldset :disabled="busy"><label>학생 이름·아이디 검색<input v-model="search" maxlength="100" placeholder="학생 검색" @input="find"/></label><label>포인트 받을 학생<select v-model="studentId" required><option disabled value="">학생 선택</option><option v-for="u in students" :key="u.id" :value="u.id">{{u.name}} · {{u.login}} · {{u.class_name}}</option></select></label><label>지급 포인트<input v-model.number="amount" type="number" min="1" max="1000000" step="1" required/><small>1회 1~1,000,000 P · 정수만 입력</small></label><label>지급 사유<input v-model="reason" required maxlength="200" placeholder="예: 과제 우수 제출, 수업 참여"/></label><div class="toolbar"><strong v-if="account">현재 보유 {{account.balance.toLocaleString()}} P</strong><span v-if="loading">포인트 조회 중…</span><button :disabled="busy||loading||!account||!reason.trim()">포인트 지급</button></div></fieldset></form><details v-if="account" class="grant-history"><summary>{{account.student.name}} 학생 관리자 지급 내역 {{account.grants.length}}건 (최근 20건)</summary><p v-if="!account.grants.length">아직 관리자 지급 내역이 없어요.</p><article v-for="g in account.grants" :key="g.id"><strong>+{{g.amount.toLocaleString()}} P</strong><span>{{g.reason}}</span><small>{{g.admin_name}} · {{new Date(g.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</small></article></details><dialog ref="dialog" class="point-grant-dialog" aria-label="학생 포인트 지급 확인" @cancel.prevent="!busy&&dialog.close()"><h2>포인트를 지급할까요?</h2><template v-if="account"><p>{{account.student.name}} · @{{account.student.login}}</p><strong class="grant-amount">+{{amount.toLocaleString()}} P</strong><p>지급 후 {{(account.balance+amount).toLocaleString()}} P</p><p class="mail-body">{{reason}}</p></template><p v-if="error" class="notice" role="alert">{{error}}</p><div class="toolbar"><button :disabled="busy" @click="grant">{{busy?'지급 중…':'지급 확정'}}</button><button class="light" :disabled="busy" @click="dialog.close()">취소</button></div></dialog></section></template>
